get_tax_settings.code:
final response = await client.taxSettings.getTaxSettings();
final taxSettings = (response.map as Map)['tax_settings'] as Map;
print(taxSettings['default_country']);
print(taxSettings['default_tax_code']);
print(taxSettings['tax_message']);

put_tax_settings.code:
final response = await client.taxSettings.putTaxSettings({
  'settings': {'tax_message': 'All prices include GST'},
});
final taxSettings = (response.map as Map)['tax_settings'] as Map;
print(taxSettings['tax_message']);
